-- Advisor do Supabase (multiple_permissive_policies), última parte (as
-- tabelas fora do fluxo de chamados; profiles fica em migração própria).
--
-- Nestas tabelas as policies antigas eram "ALL" (uma por perfil gestor) mais
-- uma de SELECT mais larga. Uma policy ALL também vale para SELECT, daí a
-- sobreposição. Agora cada tabela tem uma policy por operação:
--   gestor  = OR de todas as antigas ALL (USING e WITH CHECK eram iguais);
--   SELECT  = gestor OR a antiga policy de leitura;
--   INSERT, UPDATE, DELETE = gestor.
-- O acesso resultante é o mesmo de antes (conferido com os 4 perfis de teste).
--
-- O DO de cada tabela apaga as policies existentes dela; a lista foi
-- conferida em 23/09/2026 e são só as que este arquivo recria.

-- audit_log: só leitura
DO $$ DECLARE p text; BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='audit_log' AND cmd='SELECT' LOOP EXECUTE format('DROP POLICY %I ON public.audit_log', p); END LOOP; END $$;
CREATE POLICY audit_log_select ON public.audit_log FOR SELECT TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND changed_by IN (SELECT profiles.id FROM public.profiles WHERE profiles.company_id = (SELECT public.get_user_company_id((SELECT auth.uid()))))));

-- contracts
DO $$ DECLARE p text; BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='contracts' LOOP EXECUTE format('DROP POLICY %I ON public.contracts', p); END LOOP; END $$;
CREATE POLICY contracts_select ON public.contracts FOR SELECT TO authenticated USING (((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid()))))) OR ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR (company_id = (SELECT public.get_user_company_id((SELECT auth.uid()))) AND ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role))))));
CREATE POLICY contracts_insert ON public.contracts FOR INSERT TO authenticated WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))));
CREATE POLICY contracts_update ON public.contracts FOR UPDATE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid()))))) WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))));
CREATE POLICY contracts_delete ON public.contracts FOR DELETE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))));

