CREATE POLICY custom_field_values_update ON public.custom_field_values FOR UPDATE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR EXISTS (SELECT 1 FROM public.custom_fields cf WHERE cf.id = custom_field_values.custom_field_id AND cf.company_id = (SELECT public.get_user_company_id((SELECT auth.uid()))))) WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR EXISTS (SELECT 1 FROM public.custom_fields cf WHERE cf.id = custom_field_values.custom_field_id AND cf.company_id = (SELECT public.get_user_company_id((SELECT auth.uid())))));
CREATE POLICY custom_field_values_delete ON public.custom_field_values FOR DELETE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR EXISTS (SELECT 1 FROM public.custom_fields cf WHERE cf.id = custom_field_values.custom_field_id AND cf.company_id = (SELECT public.get_user_company_id((SELECT auth.uid())))));

