-- ticket_kb_links
DO $$ DECLARE p text; BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='ticket_kb_links' LOOP EXECUTE format('DROP POLICY %I ON public.ticket_kb_links', p); END LOOP; END $$;
CREATE POLICY ticket_kb_links_select ON public.ticket_kb_links FOR SELECT TO authenticated USING (((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (((SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role))) AND public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))))) OR (EXISTS (SELECT 1 FROM public.tickets t WHERE t.id = ticket_kb_links.ticket_id AND t.user_id = (SELECT auth.uid()))));
CREATE POLICY ticket_kb_links_insert ON public.ticket_kb_links FOR INSERT TO authenticated WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (((SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role))) AND public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid())))));
CREATE POLICY ticket_kb_links_update ON public.ticket_kb_links FOR UPDATE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (((SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role))) AND public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))))) WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (((SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role))) AND public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid())))));
CREATE POLICY ticket_kb_links_delete ON public.ticket_kb_links FOR DELETE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (((SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role))) AND public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid())))));

-- time_entries
DO $$ DECLARE p text; BEGIN FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='time_entries' LOOP EXECUTE format('DROP POLICY %I ON public.time_entries', p); END LOOP; END $$;
CREATE POLICY time_entries_select ON public.time_entries FOR SELECT TO authenticated USING (((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (user_id = (SELECT auth.uid()) AND ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid())))))) OR ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR (public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))) AND ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'technician'::public.app_role)) OR (SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role))))));
CREATE POLICY time_entries_insert ON public.time_entries FOR INSERT TO authenticated WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (user_id = (SELECT auth.uid()) AND ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))))));
CREATE POLICY time_entries_update ON public.time_entries FOR UPDATE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (user_id = (SELECT auth.uid()) AND ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid())))))) WITH CHECK ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (user_id = (SELECT auth.uid()) AND ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))))));
CREATE POLICY time_entries_delete ON public.time_entries FOR DELETE TO authenticated USING ((SELECT public.has_role((SELECT auth.uid()), 'developer'::public.app_role)) OR ((SELECT public.has_role((SELECT auth.uid()), 'admin'::public.app_role)) AND (SELECT public.is_master_company_user((SELECT auth.uid())))) OR (user_id = (SELECT auth.uid()) AND ((SELECT public.is_equipe_interna((SELECT auth.uid()))) OR public.get_ticket_company_id(ticket_id) = (SELECT public.get_user_company_id((SELECT auth.uid()))))));

